code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    row_cuts = [r for r, row in enumerate(g) if row[0] != 0 and all(v == row[0] for v in row)]
    col_cuts = [c for c in range(w) if g[0][c] != 0 and all(g[r][c] == g[0][c] for r in range(h))]
    def bands(size, cuts):
        out, start = [], 0
        for cut in cuts:
            if start < cut:
                out.append((start, cut))
            start = cut + 1
        if start < size:
            out.append((start, size))
        return out
    rows, cols = bands(h, row_cuts), bands(w, col_cuts)
    anchors = set()
    for i in range(len(cols) - 1):
        x0, x1 = cols[i]
        y0, y1 = cols[i + 1]
        if x1 - x0 != y1 - y0:
            continue
        for r0, r1 in rows:
            colors = {g[r][c] for r in range(r0, r1) for c in range(x0, x1) if g[r][c] != 0}
            if len(colors) != 1:
                continue
            color = next(iter(colors))
            if all(g[r][x0 + x] == g[r][y1 - 1 - x] for r in range(r0, r1) for x in range(x1 - x0)):
                anchors.add((i, color))
    for i, color in anchors:
        x0, x1 = cols[i]
        y0, y1 = cols[i + 1]
        width = x1 - x0
        for r0, r1 in rows:
            left = any(g[r][c] == color for r in range(r0, r1) for c in range(x0, x1))
            right = any(g[r][c] == color for r in range(r0, r1) for c in range(y0, y1))
            if left == right:
                continue
            src, dst = (x0, y0) if left else (y0, x0)
            for r in range(r0, r1):
                for x in range(width):
                    if g[r][dst + x] == 0:
                        g[r][dst + x] = g[r][src + width - 1 - x]
    return g
'''
